static void volvoxai_v1_generate_event_clear_event(
    VolvoxaiV1GenerateEvent* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    switch (message->which_event) {
        case 1:
            if (message->field_token) {
                volvoxai_v1_token_free(message->field_token);
                synurang_lite_release(allocator, message->field_token);
                message->field_token = NULL;
            }
            break;
        case 2:
            if (message->field_done) {
                volvoxai_v1_generate_done_free(message->field_done);
                synurang_lite_release(allocator, message->field_done);
                message->field_done = NULL;
            }
            break;
        default: break;
    }
    message->which_event = 0;
}
static void volvoxai_v1_image_clear_source(
    VolvoxaiV1Image* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    switch (message->which_source) {
        case 1:
            synurang_lite_bytes_clear(allocator, &message->field_encoded);
            break;
        case 2:
            if (message->field_tensor) {
                volvoxai_v1_tensor_free(message->field_tensor);
                synurang_lite_release(allocator, message->field_tensor);
                message->field_tensor = NULL;
            }
            break;
        default: break;
    }
    message->which_source = 0;
}
static void volvoxai_v1_load_model_request_clear_source(
    VolvoxaiV1LoadModelRequest* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    switch (message->which_source) {
        case 1:
            if (message->field_paths) {
                volvoxai_v1_model_paths_free(message->field_paths);
                synurang_lite_release(allocator, message->field_paths);
                message->field_paths = NULL;
            }
            break;
        case 2:
            if (message->field_inline) {
                volvoxai_v1_model_bytes_free(message->field_inline);
                synurang_lite_release(allocator, message->field_inline);
                message->field_inline = NULL;
            }
            break;
        default: break;
    }
    message->which_source = 0;
}


