static SynurangLiteStatus volvoxai_v1_activate_adapter_request_encode_into(
    const VolvoxaiV1ActivateAdapterRequest* message,
    SynurangLiteWriterInternal* writer) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    size_t i;
    if (!message || !writer) return SYNURANG_LITE_INVALID_ARGUMENT;
    (void)status;
    if (message->field_model_id.len) {
        sl_write_length_delimited(
            writer,
            1,
            message->field_model_id.data,
            message->field_model_id.len);
    }
    if (message->field_selection) {
        uint8_t* nested = NULL;
        size_t nested_len = 0;
        status = volvoxai_v1_adapter_selection_encode(
            message->field_selection, &nested, &nested_len);
        if (status != SYNURANG_LITE_OK) return status;
        sl_write_length_delimited(writer, 2, nested, nested_len);
        synurang_lite_release(message->field_selection->_allocator, nested);
    }
    (void)i;
    return writer->status;
}

SynurangLiteStatus volvoxai_v1_activate_adapter_request_encode(
    const VolvoxaiV1ActivateAdapterRequest* message,
    uint8_t** output,
    size_t* output_len) {
    SynurangLiteWriterInternal writer;
    if (!message || !output || !output_len) return SYNURANG_LITE_INVALID_ARGUMENT;
    *output = NULL;
    *output_len = 0;
    sl_writer_init(&writer, message->_allocator);
    writer.status = volvoxai_v1_activate_adapter_request_encode_into(message, &writer);
    if (writer.status != SYNURANG_LITE_OK) {
        SynurangLiteStatus status = writer.status;
        sl_writer_discard(&writer);
        return status;
    }
    *output = writer.data;
    *output_len = writer.len;
    return SYNURANG_LITE_OK;
}


static SynurangLiteStatus volvoxai_v1_adapter_capabilities_encode_into(
    const VolvoxaiV1AdapterCapabilities* message,
    SynurangLiteWriterInternal* writer) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    size_t i;
    if (!message || !writer) return SYNURANG_LITE_INVALID_ARGUMENT;
    (void)status;
    if (message->field_kinds.len) {
        SynurangLiteWriterInternal packed;
        sl_writer_init(&packed, message->_allocator);
        for (i = 0; i < message->field_kinds.len; ++i) {
            sl_write_enum_raw(
                &packed, message->field_kinds.data[i]);
        }
        if (packed.status == SYNURANG_LITE_OK) {
            sl_write_length_delimited(writer, 1, packed.data, packed.len);
        }
        status = packed.status;
        sl_writer_discard(&packed);
        if (status != SYNURANG_LITE_OK) return status;
    }
    if (message->field_immutable_versions) {
        sl_write_bool(
            writer, 2, message->field_immutable_versions);
    }
    if (message->field_hot_swap) {
        sl_write_bool(
            writer, 3, message->field_hot_swap);
    }
    if (message->field_per_batch_routing) {
        sl_write_bool(
            writer, 4, message->field_per_batch_routing);
    }
    if (message->field_adapter_only_persistence) {
        sl_write_bool(
            writer, 5, message->field_adapter_only_persistence);
    }
    if (message->field_merge_unmerge) {
        sl_write_bool(
            writer, 6, message->field_merge_unmerge);
    }
    if (message->field_gpu_grouped_matmul) {
        sl_write_bool(
            writer, 7, message->field_gpu_grouped_matmul);
    }
    (void)i;
    return writer->status;
}

SynurangLiteStatus volvoxai_v1_adapter_capabilities_encode(
    const VolvoxaiV1AdapterCapabilities* message,
    uint8_t** output,
    size_t* output_len) {
    SynurangLiteWriterInternal writer;
    if (!message || !output || !output_len) return SYNURANG_LITE_INVALID_ARGUMENT;
    *output = NULL;
    *output_len = 0;
    sl_writer_init(&writer, message->_allocator);
    writer.status = volvoxai_v1_adapter_capabilities_encode_into(message, &writer);
    if (writer.status != SYNURANG_LITE_OK) {
        SynurangLiteStatus status = writer.status;
        sl_writer_discard(&writer);
        return status;
    }
    *output = writer.data;
    *output_len = writer.len;
    return SYNURANG_LITE_OK;
}


static SynurangLiteStatus volvoxai_v1_adapter_info_encode_into(
    const VolvoxaiV1AdapterInfo* message,
    SynurangLiteWriterInternal* writer) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    size_t i;
    if (!message || !writer) return SYNURANG_LITE_INVALID_ARGUMENT;
    (void)status;
    if (message->field_adapter) {
        uint8_t* nested = NULL;
        size_t nested_len = 0;
        status = volvoxai_v1_adapter_version_ref_encode(
            message->field_adapter, &nested, &nested_len);
        if (status != SYNURANG_LITE_OK) return status;
        sl_write_length_delimited(writer, 1, nested, nested_len);
        synurang_lite_release(message->field_adapter->_allocator, nested);
    }
    if (message->field_manifest) {
        uint8_t* nested = NULL;
        size_t nested_len = 0;
        status = volvoxai_v1_adapter_manifest_encode(
            message->field_manifest, &nested, &nested_len);
        if (status != SYNURANG_LITE_OK) return status;
        sl_write_length_delimited(writer, 2, nested, nested_len);
        synurang_lite_release(message->field_manifest->_allocator, nested);
    }
    if (message->field_parent_version_id.len) {
        sl_write_length_delimited(
            writer,
            3,
            message->field_parent_version_id.data,
            message->field_parent_version_id.len);
    }
    if (message->field_source_path.len) {
        sl_write_length_delimited(
            writer,
            4,
            message->field_source_path.data,
            message->field_source_path.len);
    }
    if (message->field_size_bytes != 0) {
        sl_write_int64(
            writer, 5, message->field_size_bytes);
    }
    if (message->field_active) {
        sl_write_bool(
            writer, 6, message->field_active);
    }
    if (message->field_merged) {
        sl_write_bool(
            writer, 7, message->field_merged);
    }
    if (message->field_optimizer_step != 0) {
        sl_write_int64(
            writer, 8, message->field_optimizer_step);
    }
    (void)i;
    return writer->status;
}

